import { supabase } from './supabase.js';

const $=selector=>document.querySelector(selector),esc=(value='')=>String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const labels={announcement:'Annonce',discussion:'Discussion',question:'Question',success:'Réussite',resource:'Ressource'};
const feed=$('#posts-feed'),dialog=$('#post-thread-dialog');let user,ownProfile,posts=[],profiles=new Map(),filter='all',activePost,room;
const date=value=>new Intl.DateTimeFormat('fr-FR',{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(value));
const profile=id=>profiles.get(id)||{display_name:'Membre STOA',avatar_url:null};
const avatar=item=>item.avatar_url?`<span class="post-avatar has-image" style="background-image:url('${esc(item.avatar_url)}')"></span>`:`<span class="post-avatar">${esc((item.display_name||'S')[0].toUpperCase())}</span>`;

async function loadProfiles(ids){const missing=[...new Set(ids.filter(Boolean))].filter(id=>!profiles.has(id));if(!missing.length)return;const {data}=await supabase.rpc('get_community_profiles',{profile_ids:missing});(data||[]).forEach(item=>profiles.set(item.id,item));}
async function loadPosts(){
  const {data,error}=await supabase.from('community_posts').select('*,community_post_comments(count),community_post_reactions(id,user_id,emoji)').order('pinned_at',{ascending:false,nullsFirst:false}).order('created_at',{ascending:false});
  if(error){feed.innerHTML=`<div class="posts-empty"><h2>Le fil est momentanément indisponible.</h2><p>${esc(error.message)}</p></div>`;return;}
  posts=data||[];await loadProfiles(posts.map(post=>post.author_id));renderPosts();
}
function renderPosts(){
  const shown=posts.filter(post=>filter==='all'||post.category===filter);
  feed.innerHTML=shown.length?shown.map(post=>{const author=profile(post.author_id),reactions=post.community_post_reactions||[],counts=['❤','👏','💡'].map(emoji=>({emoji,count:reactions.filter(item=>item.emoji===emoji).length,own:reactions.some(item=>item.emoji===emoji&&item.user_id===user.id)}));return `<article class="post-card ${post.pinned_at?'is-pinned':''}" data-post-id="${post.id}">${post.pinned_at?'<div class="post-pinned-label">ÉPINGLÉ PAR STOA</div>':''}<header>${avatar(author)}<div><strong>${esc(author.display_name)}</strong><span>${date(post.created_at)} · ${labels[post.category]}</span></div>${ownProfile?.role==='admin'?`<div class="post-admin-actions"><button data-post-pin title="${post.pinned_at?'Désépingler':'Épingler'}">⌖</button><button data-post-delete title="Supprimer">×</button></div>`:''}</header><div class="post-copy"><h2>${esc(post.title)}</h2><p>${esc(post.content).replaceAll('\n','<br>')}</p></div>${post.image_url?`<img class="post-image" src="${esc(post.image_url)}" alt="" loading="lazy">`:''}<footer><div class="post-reactions">${counts.map(item=>`<button class="${item.own?'active':''}" data-post-reaction="${item.emoji}">${item.emoji}${item.count?` <span>${item.count}</span>`:''}</button>`).join('')}</div><button class="post-comments-button" data-post-comments>${post.community_post_comments?.[0]?.count||0} commentaire${Number(post.community_post_comments?.[0]?.count||0)>1?'s':''} <span>→</span></button></footer></article>`;}).join(''):'<div class="posts-empty"><span>✦</span><h2>Aucune publication ici pour le moment.</h2><p>Les publications de l’équipe STOA apparaîtront dans cet espace.</p></div>';
}
async function openThread(post){
  activePost=post;const {data:comments}=await supabase.from('community_post_comments').select('*').eq('post_id',post.id).order('created_at');await loadProfiles((comments||[]).map(item=>item.user_id));
  const author=profile(post.author_id);$('#post-thread-content').innerHTML=`<article class="post-thread-original"><span class="eyebrow">${labels[post.category]}</span><h2>${esc(post.title)}</h2><p>${esc(post.content).replaceAll('\n','<br>')}</p><small>Par ${esc(author.display_name)} · ${date(post.created_at)}</small></article><div class="post-thread-comments">${(comments||[]).map(comment=>{const member=profile(comment.user_id);return `<article>${avatar(member)}<div><header><strong>${esc(member.display_name)}</strong><time>${date(comment.created_at)}</time></header><p>${esc(comment.content).replaceAll('\n','<br>')}</p></div></article>`;}).join('')||'<p class="thread-empty">Soyez la première personne à répondre.</p>'}</div>`;if(!dialog.open)dialog.showModal();
}

async function init(){
  user=(await supabase.auth.getSession()).data.session?.user;if(!user)return;ownProfile=(await supabase.from('profiles').select('role').eq('id',user.id).maybeSingle()).data;
  if(ownProfile?.role==='admin')$('#post-composer').hidden=false;await loadPosts();
  room=supabase.channel('community-posts-feed').on('postgres_changes',{event:'*',schema:'public',table:'community_posts'},loadPosts).on('postgres_changes',{event:'*',schema:'public',table:'community_post_comments'},loadPosts).subscribe();
  addEventListener('pagehide',()=>{if(room)supabase.removeChannel(room)},{once:true});
}
$('#post-filters').addEventListener('click',event=>{const button=event.target.closest('[data-post-filter]');if(!button)return;filter=button.dataset.postFilter;$('#post-filters').querySelectorAll('button').forEach(item=>item.classList.toggle('active',item===button));renderPosts();});
feed.addEventListener('click',async event=>{const card=event.target.closest('[data-post-id]');if(!card)return;const post=posts.find(item=>item.id===card.dataset.postId);if(event.target.closest('[data-post-comments]'))return openThread(post);const reaction=event.target.closest('[data-post-reaction]');if(reaction){const existing=post.community_post_reactions?.find(item=>item.emoji===reaction.dataset.postReaction&&item.user_id===user.id);if(existing)await supabase.from('community_post_reactions').delete().eq('id',existing.id);else await supabase.from('community_post_reactions').insert({post_id:post.id,user_id:user.id,emoji:reaction.dataset.postReaction});return loadPosts();}if(event.target.closest('[data-post-pin]')){await supabase.from('community_posts').update({pinned_at:post.pinned_at?null:new Date().toISOString()}).eq('id',post.id);return loadPosts();}if(event.target.closest('[data-post-delete]')){if(confirm('Supprimer définitivement cette publication ?')){await supabase.from('community_posts').delete().eq('id',post.id);loadPosts();}}});
$('#post-form').addEventListener('submit',async event=>{event.preventDefault();const status=$('#post-form-status');status.textContent='Publication…';const {error}=await supabase.from('community_posts').insert({author_id:user.id,category:$('#post-category').value,title:$('#post-title').value.trim(),content:$('#post-content').value.trim(),image_url:$('#post-image').value.trim()||null,pinned_at:$('#post-pinned').checked?new Date().toISOString():null});status.textContent=error?error.message:'Publication ajoutée.';if(!error){event.currentTarget.reset();loadPosts();}});
$('#post-comment-form').addEventListener('submit',async event=>{event.preventDefault();const content=$('#post-comment-content').value.trim();if(!content||!activePost)return;const {error}=await supabase.from('community_post_comments').insert({post_id:activePost.id,user_id:user.id,content});$('#post-comment-status').textContent=error?error.message:'Réponse publiée.';if(!error){$('#post-comment-content').value='';await openThread(activePost);loadPosts();}});
$('#post-thread-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close()});
init();
